INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64932012', 64932012, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pengembangan Fitur Antarmuka Pengguna Portal Publik Digital RKP Tahun Anggaran 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 40909092, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Posisi Jasa Konsultansi Penyusunan Laman Desain Antarmuka Portal Digital RKP di Direktorat Sinergi dan Tata Kelola Perencanaan Pembangunan Tahun 2026 memiliki Ruang Lingkup sebagai berikut: 1. Merancang antarmuka portal publik sebagai pelengkap dokumen RKP, yang menjadi bagian dari implementasi dari konsep Transformasi RKP 2027, sebagai dasar pengembangan sistem. 2. Menganalisis kebutuhan penyajian informasi RKP secara visual untuk pengguna publik pada portal publik RKP 2027. 3. Menyajikan kebutuhan portal publik RKP 2027 dalam bentuk wireframe, prototype tampilan, dan rekomendasi tampilan visual antarmuka.', '1. Pendidikan minimal (S1) di bidang yang relevan, baik didalam ataupun diluar negeri dan dapat dibuktikan dengan Ijazah atau dokumen resmi kelulusan atau sertifikat kelulusan; 2. Memiliki pengalaman paling kurang 1 (satu) tahun di bidang perancangan antarmuka dan/atau pengalaman pengguna untuk produk digital; 3. Memiliki portofolio karya UI/UX yang dapat menunjukkan kemampuan dalam menyusun struktur informasi, alur pengguna, serta desain antarmuka digital; 4. Memiliki kemampuan komunikasi yang efektif, baik lisan maupun tulisan dalam menyampaikan ide desain dan berdiskusi dengan tim teknis maupun non-teknis 5. Bersedia bekerja secara mandiri maupun dalam tim, serta memiliki inisiatif dalam menyelesaikan pekerjaan administratif dan teknis 6. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; 7. Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; 8. Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP). 9. Memiliki bukti potong pajak atas penghasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; 10. Bekerja berdasarkan output keluaran, dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan. 11. Memiliki identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP)/Paspor/Surat Keterangan Domisili Tinggal', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1860447);
