INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65019087', 65019087, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN PENYUSUNAN KEBIJAKAN SANITASI KEGIATAN KOORDINASI PROGRAM SWASEMBADA AIR (AIR MINUM DAN SANITASI NASIONAL)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Menelaah dan menganalisis isu serta tantangan penyediaan infrastruktur dan layanan sanitasi di tingkat pemerintah pusat maupun daerah; 2. Melakukan penyiapan data, benchmarking kebijakan, serta pencatatan kronologi kegiatan tahunan dalam RKP bidang sanitasi; 3. Memfasilitasi perencanaan, penyiapan daerah maupun pelaksanaan program khusus seperti PHLN serta kerjasama bilateral dan multilateral lainnya yang bersumber dari pendanaan/pembiayaan dalam maupun luar negeri; 4. Menelaah dan menganalisis gap serta potensi dalam kajian pendalaman konvergensi sanitasi aman dan pengembangan sanitasi berbasis ketahanan iklim; 5. Mendukung pelaksanaan penyusunan kebijakan integrasi kelembagaan air minum dan sanitasi; 6. Menyusun laporan bulanan Jasa Konsultan Junior Perancangan Kebijakan Sanitasi', '1. Pendidikan minimal S1 perencanaan wilayah dan kota/planologi/teknik lingkungan/manajemen infrastruktur (dibuktikan dengan ijazah); 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 3. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki pengalaman kerja di bidang Perencanaan minimal 2 tahun, pengalaman di bidang air minum atau sanitasi dan/atau perencanaan kewilayahan merupakan nilai tambah (dibuktikan dengan kontrak); 7. Memiliki pengalaman dalam melakukan perencanaan program dan kegiatan di lingkup pemerintahan, pengalaman di bidang air minum atau sanitasi (dibuktikan dengan kontrak); 8. Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah (dibuktikan dengan kontrak).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1864456);
