INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64978012', 64978012, 'analyze_legacy', 'Kab. Probolinggo', 'kabkota', 'Puskesmas Klenang Kidul', 'Belanja Makanan dan Minuman Rapat_Pelayanan dan Penunjang Pelayanan BLUD_Puskesmas Klenang Kidul', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 11600000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Belanja Makanan dan Minuman Rapat merupakan kegiatan pengadaan konsumsi yang diperuntukkan bagi pelaksanaan rapat koordinasi, rapat internal, rapat evaluasi kinerja, serta kegiatan perencanaan dan penunjang pelayanan lainnya di lingkungan BLUD UPT Puskesmas Klenang Kidu', 'Spesifikasi Belanja Makanan dan Minuman Rapat meliputi penyediaan konsumsi berupa makanan ringan dan/atau makanan berat serta minuman bagi peserta rapat, yang disesuaikan dengan jumlah peserta dan durasi kegiatan. Bahan yang diperlukan antara lain nasi kotak atau snack box, lauk pauk, kue, buah, air mineral kemasan, teh, dan/atau kopi, dengan ketentuan makanan layak konsumsi, higienis, berkualitas baik, serta memenuhi standar kesehatan. Seluruh konsumsi disediakan tepat waktu, dalam kemasan yang rapi dan aman, serta sesuai dengan kebutuhan kegiatan Pelayanan dan Penunjang Pelayanan BLUD UPT Puskesmas Klenang Kidul.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1865369);
