INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65018170', 65018170, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN PENYUSUNAN KEBIJAKAN INOVASI SANITASI KEGIATAN KOORDINASI PROGRAM SWASEMBADA AIR (AIR MINUM  DAN SANITASI NASIONAL)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Menelaah isu pemenuhan sanitasi aman dari hulu hingga ke hilir dengan fokus pada gap rantai layanan sanitasi; 2. Menelaah dan menganalisis potensi inovasi dalam pengembangan teknologi sanitasi; 3. Menelaah dan menganalisis gap serta potensi inovasi bauran pendanaan dan pembiayaan untuk sektor sanitasi; 4. Memfasilitasi perencanaan, penyiapan daerah maupun pelaksanaan program terkait Transfer ke Daerah (TKD), seperti diantaranya Dana Alokasi Khusus (DAK), Dana Alokasi Umum (DAU) dan lain sebagainya; 5. Menelaah dan menganalisis gap serta potensi dalam kajian pendalaman konvergensi sanitasi aman dan pengembangan sanitasi berbasis ketahanan iklim; 6. Menyusun laporan bulanan Jasa Konsultan Junior Inovasi Kebijakan Sanitasi.', '1. Pendidikan minimal S1 jurusan teknik Lingkungan/perencanaan wilayah dan kota/planologi/manajemen infrastruktur; 2. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam bidang air minum / sanitasi / persampahan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dibuktikan dengan jumlah kontrak kerja/lama kontrak kerja; 4. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 5. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki pengalaman kerja di bidang Perencanaan minimal 3 tahun, pengalaman di bidang air minum atau sanitasi dan/atau perencanaan kewilayahan merupakan nilai tambah (dibuktikan dengan kontrak); 7. Memiliki pengalaman dalam melakukan perencanaan program dan kegiatan di lingkup pemerintahan, pengalaman di bidang air minum atau sanitasi (dibuktikan dengan kontrak); 8. Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1866524);
