INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65041095', 65041095, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database pada Sub Sistem e-Monev Gen 4.0', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 98400000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database pada Sub Sistem e-Monev Gen 4.0 adalah sebagai berikut: Penyusunan dan pengembangan diagram alur kerja aplikasi rinci dan diagram yang menggambarkan input, output dan operasi logis dan mengubahnya menjadi serangkaian instruksi dikodekan dalam Bahasa computer (aplikasi). Pelaksanaan proses extract, transform, load (ETL) data RKAKL. Pelaksanaan pengujian fungsional program dan aplikasi. Pelaksanaan pemeliharaan dan pembaharuan atas aplikasi E-Monev. Pelaksanaan penyiapan dan pengelolaan serta pemanfaatan aplikasi E-Monev. Penyusunan laporan akhir Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database pada Sub Sistem e-Monev Gen 4.0.', 'Output kegiatan Jasa Konsultan Junior Pengembangan Fitur/Aplikasi/Database pada Sub Sistem e-Monev Gen 4.0 meliputi tersusunnya Laporan Pengembangan Fitur/Aplikasi/Database pada Sub Sistem e-Monev Gen 4.0. Adapun rincian keluaran yang akan dilaporkan pada setiap termin adalah sebagai berikut: No Periode Keluaran (Output) 1 Termin I Laporan analisis kebutuhan sistem dan diagram alur kerja (flowchart) yang menggambarkan input, proses, dan output aplikasi. 2 Termin II Laporan desain sistem lanjutan serta modul aplikasi hasil implementasi awal instruksi program (coding) sesuai diagram alur kerja. 3 Termin III Laporan data RKAKL yang telah melalui proses Extract, Transform, dan Load (ETL) serta terintegrasi ke dalam aplikasi E-Monev. 4 Termin IV Laporan pengujian dan percobaan program/aplikasi perangkat lunak yang menunjukkan fungsi sistem berjalan sesuai spesifikasi aplikasi E-Monev. 5 Termin V Laporan pembangunan Fitur/aplikasi E-Monev dan laporan hasil pemeliharaan dan pembaharuan serta dukungan penugasan terkait penyiapan, pengelolaan, dan pemanfaatan aplikasi E-Monev. 6 Termin VI Laporan Pengembangan Fitur/Aplikasi/Database pada Sub Sistem e-Monev Gen 4.0.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1867572);
