INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65040493', 65040493, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional  (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 95172000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Junior Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) adalah sebagai berikut: Menyelenggarakan kegiatan pengembangan kapasitas sumber daya manusia dalam penerapan Prinsip Budaya Risiko. Membuat modul panduan fasilitator dan narasumber pelatihan Budaya Risiko. Membuat strategi pengembangan SDM Budaya Risiko: Gap analisis antara kompetensi eksisting dan kompetensi target. Membuat pengukuran hasil peningkatan kompetensi SDM. Membuat evaluasi efektifitas program pengembangan kapasitas SDM dalam pengembangan budaya risiko. Membuat rencana tindak lanjut (action plan) penguatan SDM Budaya Risiko. Membuat Laporan Akhir Konsultan Junior Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN).', 'Output utama Jasa Konsultan Junior Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) adalah tersusunnya dokumen komprehensif yang memuat capaian penguatan kapasitas sumber daya manusia dalam penerapan budaya risiko pembangunan secara terintegrasi, terukur, dan berkelanjutan, mencakup hasil asesmen tingkat pemahaman, sikap, dan perilaku SDM, analisis kesenjangan kompetensi, efektivitas program pengembangan, serta kerangka pengembangan kompetensi yang selaras dengan peran MRPN, dilengkapi dengan instrumen dan modul pendukung, serta rekomendasi kebijakan dan roadmap implementatif yang dituangkan dalam Laporan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) sebagai acuan pengambilan keputusan dan keberlanjutan penguatan budaya risiko dalam manajemen risiko pembangunan nasional. Jasa Konsultan Junior Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko yang memiliki keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan penyelenggaraan kegiatan pengembangan kapasitas sumber daya manusia dalam penerapan Prinsip Budaya Risiko. 2 Termin 2 Laporan modul panduan fasilitator dan narasumber pelatihan Budaya Risiko. 3 Termin 3 Laporan strategi pengembangan SDM Budaya Risiko: Gap analisis antara kompetensi eksisting dan kompetensi target. 4 Termin 4 Laporan pengukuran peningkatan kompetensi SDM. 5 Termin 5 Laporan evaluasi efektifitas program pengembangan kapasitas SDM dalam pengembangan budaya risiko. 6 Termin 6 Laporan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan SDM Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1867784);
