INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65041273', 65041273, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RUMAH SAKIT UMUM H ADAM MALIK MEDAN', 'Pengadaan Farmaka Kebutuhan Sub. Instalasi Kedokteran Nuklir RSUP H. Adam Malik Medan Tahun 2026', 'Barang', 'Tender', 'Sumatera Utara, Medan (Kota)', 410310965, 'February 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 0, '1 Tahun', 'Pengadaan Farmaka Kebutuhan Sub. Instalasi Kedokteran Nuklir RSUP H. Adam Malik Medan Tahun 2026', '"- Prostate-Specific Membrane Antigen (PSMA) 1. Fungsinya untuk apa Mendeteksi kanker Prostas atau Pemeriksaan Lainnya yang mengunakan PSMA 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 4 jam pada suhu 25 oC - Mercaptoacetyltriglycine / MAG3 1. Fungsinya untuk pemeriksaan evaluasi nefrologi, urologi atau Pemeriksaan Lainnya yang mengunakan MAG3 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -CIPROFLOKSASIN 1. Fungsinya untuk pemeriksaan Sidik infeksi atau Pemeriksaan Lainnya yang mengunakan CIPROFLOKSASIN 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 4 jam pada suhu 25 oC -Nano Albumon / NAA 1. Fungsinya untuk pemeriksaan lymphatic Skintigraphy, Bone Marrow Scaning atau Pemeriksaan Lainnya yang mengunakan NAA 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -Makro Albumon / MAA 1. Fungsinya untuk Perfusi lung Skintigraphy atau Pemeriksaan Lainnya yang mengunakan MAA 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -Dimercapto Succinic Acid (DMSA) 1. Fungsinya untuk pemeriksaan Renal Imaging atau Pemeriksaan Lainnya yang mengunakan DMSA 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -Mebrofenin (BRIDA) 1. Fungsinya untuk pemeriksaan hepatobilier (HIDA scan) atau Pemeriksaan Lainnya yang mengunakan BRIDA 2. Efesiensi labeling diatas 90% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -Diethylene triamine pentaacetate (DTPA) 1. Fungsinya untuk Skintigrafi renal, Pemeriksaan Ventilasi Paru atau Pemeriksaan Lainnya yang mengunakan DTPA 2. Dapat dilabel dengan Tc-99m diatas 200 mCi dengan efesiensi labeling minimal 95% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -Asam medronat/ methylenediphosponic acid (MDP) 1. Fungsinya untuk pemeriksaan bone scan (pemeriksaan tulang) atau Pemeriksaan Lainnya yang mengunakan MDP 2. Dapat dilabel dengan Tc-99m diatas 300 mCi dengan efesiensi labeling minimal 95% 3. Stabilitas setelah dilabel minimal 6 jam pada suhu 25 oC -Methoxyisobutyl Isonitrile (MIBI) 1. Fungsinya untuk Pemeriksaan otot jantung (myocardium), hipertiroidisme (parathyroid adenomas), Sidik seluruh tubuh atau beberapa kasus kanker payudara Pemeriksaan Lainnya yang mengunakan MIBI 2. Dapat dilabel dengan Tc-99m minimal 300 mCi (1-5 mL) dengan efesiensi labeling minimal 90% 3. Stabilitas setelah dilabel minimal 6 jam suhu pada suhu 25 oC"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1867946);
