INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65041379', 65041379, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pengembangan Fitur/Aplikasi/Database dan Integrasi Sistem Informasi MRPN dengan E-Monev', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan yang akan dilakukan oleh Jasa Konsultan Pengembangan Fitur/Aplikasi/Database dan Integrasi Sistem Informasi MRPN dengan E-Monev ini meliputi: Melakukan analisis kebutuhan dan perancangan teknis pengembangan Sistem Informasi Manajemen Risiko Pembangunan Nasional (MRPN) sesuai dengan ketentuan Peraturan Presiden Nomor 39 Tahun 2023. Mengembangkan sistem informasi MRPN berbasis web yang mencakup pengelolaan data risisko, proses bisnis manajemen risiko, dan integrasi data antar Kementerian/Lembaga/Pemerintah Daerah. Mengembangkan fitur dashboard visualisasi data risiko yang interaktif untuk mendukung penyajian informasi secara komprehensif kepada pimpinan dan pengambil keputusan. Melakukan pengujian fungsionalitas sistem informasi MRPN untuk memastikan kinerja aplikasi berjalan optimal, aman, stabil, serta sesuai kebutuhan pengguna. Melakukan penguatan keamanan sistem informasi MRPN dengan menerapkan prinsip keamanan aplikasi sesuai standart pengamanan sistem informasi nasional. Memberikan pendampingan teknis dan alih pengetahuan (knowledge transfer) kepada tim internal dalam pengelolaan dan pengembangan lanjutan sistem. Menyusun dokumentasi teknis pengembangan sistem informasi MRPN secara lengkap, baik dokumentasi pengembangan aplikasi, konfigurasi sistem, maupun prosedur operasional sistem. Menyusun laporan akhir jasa konsultan programmermer.', 'Hasil kerja Jasa Konsultan Pengembangan Fitur/Aplikasi/Database dan Integrasi Sistem Informasi MRPN dengan E-Monev ini adalah Laporan Pengembangan Fitur/Aplikasi/Database dan Integrasi Sistem Informasi MRPN dengan E-Monev dengan waktu penyelesaian selama 11 (sebelas) bulan. Jasa Konsultan Pengembangan Fitur/Aplikasi/Database dan Integrasi Sistem Informasi MRPN dengan E-Monev dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko memiliki keluaran setiap periode terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan finalisasi kebutuhan, analisis sistem, dan penyusunan perancangan teknis pengembangan Sistem Informasi MRPN 2 Termin 2 Laporan Pengembangan modul utama aplikasi MRPN, termasuk pengelola data risiko dan proses bisnis manajemen risiko 3 Termin 3 Laporan pengembangan fitur dashboard visualisasi data risiko dan integrasi data antar Kementerian/Lembaga 4 Termin 4 Laporan uji coba fungsionalitas sistem (system testing), debugging, penyempurnaan aplikasi, serta penguatan keamanan sistem 5 Termin 5 Laporan finalisasi pengembangan, penyususnan dokumentasi teknis, dan knowledge transfer kepada tim internal 6 Termin 6 Laporan Pengembangan Fitur/Aplikasi/Database dan Integrasi Sistem Informasi MRPN dengan E-Monev', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1869559);
