INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65019249', 65019249, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Buku Profil Program Unggulan dan Panduan Teknis Praktik Baik Program Unggulan Daerah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 324000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Lingkup Kegiatan untuk Jasa Konsultan Penyusunan Buku Profil Program Unggulan dan Panduan Teknis Praktik Baik Program Unggulan Daerah, meliputi: 1. Melakukan telaah terhadap inovasi/program unggulan daerah PPD periode tahun 2025 – 2026 dengan pendalaman terhadap konsistensi perencanaan 2026; 2. Melakukan identifikasi dan analisis terhadap inovasi/program unggulan daerah dengan pendekatan kriteria praktik baik; 3. Melakukan tinjauan ke daerah terpilih yang memiliki inovasi/program unggulan dan praktik baik melaui kegiatan wawancara atau focus group discussion dengan pendekatan kriteria praktik baik; 4. Identifikasi dan analisis terhadap efektifitas inovasi/program unggulan dan praktik baik dalam perencanaan dan penganggaran, dampak nyata dimasyarakat dan keberlanjutan program; 5. Penyusunan dokumen sebagai dasar penyusunan buku profil inovasi/program unggulan dan penyusunan panduan teknis praktik baik sebagai acuan bagi daerah lain yang akan melakukan replikasi. Pemanfaatan hasil TA bagi tusi ASN', 'Keluaran secara umum adalah: 1. Menyusun konsep PPD tahun 2026 yang terintegrasi dengan Program Prioritas Presiden, dan SEB Kemendagri dan Bappenas dalam Pembinaan dan pengawasan kinerja kepala daerah dan wakil kepala daerah dalam melaksanakan program strategis nasional tahun 2025-2029 pada penyelenggaraan pemerintahan daerah; 2. Mendukung terselengarakanya pelaksanaan Penghargaan Pembangunan Daerah 2026 dengan komponen penilaian fokus pada perencanaan, pencapaian dan program unggulan dalam pelaksanaan pembangunan; 3. Menyusun buku kerja inovatif daerah berdasarkan program unggulan daerah yang difokuskan pada tematik mendukung pertumbuhan tinggi berkelanjutan, dampak yang jelas bagi masyarakat dan program unggulan yang berkelanjutan. Keluaran secara khusus adalah: 1. Tersedianya konsep PPD yang terintegrasi untuk pelaksanaan program tahun 2026; 2. Tersedianya sejumlah inovasi/program unggulan daerah dan praktik baik yang dinilai berdasarkan kriteria yang dapat dilakukan pendalaman dan pengujian sesuai dengan kriteria; 3. Tersusunnya buku profil program unggulan terpilih dan panduan teknis praktik baik suatu daerah sebagai acuan bagi daerah lain yang akan melakukan replikasi. Rincian keluaran yang akan di laporkan pada setiap termin adalah sebagai berikut: No Termin Keluaran Per Termin 1 Termin 1 Konsep PPD 2026 (kolaborasi dengan Kemendagri-SEB, aspek evaluasi, pengendalian pencapaian, diarahkan ke prioritas presiden dan evaluasi kinerja kepala daerah dalam menjalankan program Pro-SN) serta perumusan tematik program unggulan 2 Termin 2 ● Hasil Pelaksanaan sosialisasi konsep PPD 2026, program unggulan ditingkat provinsi, kabupaten dan kota ● Teknis submit dokumen perencanaan ● Penyusunan dan penetapan tim penilai teknis, dan tim penilai ahli utama, serta tim penilai independen 3 Termin 3 ● Jumlah kabupaten dan kota Hasil penilaian provinsi terhadap kabupaten dan kota yang diikutkan dalam pelaksanaan PPD ● Jumlah provinsi, kabupaten, kota hasil penilaian TPT yang akan ditindanjuti ke tahap selanjutnya 4 Termin 4 ● Jumlah provinsi, kabupaten kota yang ditindaklanjuti kunjungan lapangan sebagai validasi hasil penilaian teknis ● Jumlah provinsi, kabupaten, kota yang masuk ke tahap berikutnya 5 Termin 5 ● Hasil pleno penetapan Jumlah provinsi, kabupaten, kota yang ditetapkan menjadi 10 besar, 5 besar dan 3 besar ● Pendalaman terhadap dokumen tematik program unggulan terbaik dari pemenang, pengelompokan dan penyusunan outline buku praktik baik, dan outline penyusunan panduan replikasi 6 Termin 6 ● Buku Praktik baik tematik program unggulan dari tingkat provinsi ● Pelaksanaan Knowledge sharing praktik baik tematik program unggulan ● Konsep PPD 2027 (aspek, kriteria, dan tematik program unggulan) ● Laporan akhir (kompilasi dari laporan triwulan)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1869630);
